import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Menu","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/menu.md","filePath":"03-developer/models/menu.md"}`),a={name:`03-developer/models/menu.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="menu" tabindex="-1">Menu <a class="header-anchor" href="#menu" aria-label="Permalink to “Menu”">​</a></h1><p>The <code>Menu</code> model is used to define site menus. Each menu stores its name and creator, and its items are retrieved through the relationship with the <code>Item</code> model. Each item&#39;s structure, destination, order, and hierarchy are defined in the <code>Item</code> model.</p><h2 id="menus-table-structure" tabindex="-1"><code>menus</code> table structure <a class="header-anchor" href="#menus-table-structure" aria-label="Permalink to “menus table structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Menu ID</td></tr><tr><td><code>name</code></td><td>VARCHAR(255)</td><td>No</td><td>Menu name</td></tr><tr><td><code>user_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the user who created the menu; associated with the <code>users</code> table</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Soft-deletion time</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of last update</td></tr></tbody></table><h2 id="properties-and-methods" tabindex="-1">Properties and methods <a class="header-anchor" href="#properties-and-methods" aria-label="Permalink to “Properties and methods”">​</a></h2><h3 id="mrohps" tabindex="-1"><code>$mrohps</code> <a class="header-anchor" href="#mrohps" aria-label="Permalink to “$mrohps”">​</a></h3><p>List of models supported by this system as destinations that can be linked to menu items:</p><ul><li><code>Product</code> — product</li><li><code>Post</code> — post</li><li><code>Group</code> — post groups</li><li><code>Category</code> — product category</li><li><code>Clip</code> — video content</li><li><code>Gallery</code> — image gallery</li></ul><p>This list specifies the classes allowed to be linked to menu items. The variable name is preserved as it appears in the current code.</p><h3 id="items" tabindex="-1"><code>items()</code> <a class="header-anchor" href="#items" aria-label="Permalink to “items()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <a href="./item.html">Item</a> model and sorts the items belonging to the menu by the <code>sort</code> field in ascending order.</p><p>Each menu can have multiple items; the parent-child structure and how each item&#39;s destination is determined are managed by the <code>Item</code> model.</p><h2 id="database-notes" tabindex="-1">Database notes <a class="header-anchor" href="#database-notes" aria-label="Permalink to “Database notes”">​</a></h2><ul><li>The <code>user_id</code> field has a foreign key to the <code>users</code> table.</li><li>When a user or menu is deleted, the database may reject the deletion if dependent records exist, due to the <code>ON DELETE RESTRICT</code> setting.</li><li>The table has a <code>deleted_at</code> field; however, soft-deletion behavior in practice depends on the <code>Menu</code> model&#39;s configuration.</li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};